package com.wailsvlr.prism.gui;

import com.wailsvlr.prism.render.Draw;
import com.wailsvlr.prism.util.ColorUtil;
import com.wailsvlr.prism.util.HeatMap;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.input.MouseButtonEvent;
import net.minecraft.network.chat.Component;
import net.minecraft.util.FormattedCharSequence;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * The heat map: every 1024x1024 area BaseHunter landed in, coloured by how much player activity it saw, with the
 * bases (green intact, orange maybe raided, red raided) and trails it found. Click one to make it your target.
 */
public class HeatMapScreen extends Screen {
	private static final int INTACT = 0x22C55E, MAYBE = 0xFFA500, RAIDED = 0xFF3030, UNCHECKED = 0xA0A8B8, TRAIL = 0x22D3EE;

	private double cx, cz;
	/** Blocks per GUI pixel. */
	private double bpp = 32;
	private double pressX, pressY;
	private boolean dragged;

	public HeatMapScreen() {
		super(Component.literal("Legit Heat Map"));
	}

	@Override
	protected void init() {
		if (minecraft != null && minecraft.player != null && cx == 0 && cz == 0) {
			cx = minecraft.player.getX();
			cz = minecraft.player.getZ();
		}
	}

	@Override
	public boolean isPauseScreen() { return false; }

	private float sx(double x) { return (float) (width / 2.0 + (x - cx) / bpp); }

	private float sy(double z) { return (float) (height / 2.0 + (z - cz) / bpp); }

	private static int statusColor(HeatMap.Marker m) {
		if (m.type.equals("trail")) return TRAIL;
		return switch (m.status == null ? "" : m.status) {
			case "Intact" -> INTACT;
			case "Maybe raided" -> MAYBE;
			case "Raided" -> RAIDED;
			default -> UNCHECKED;
		};
	}

	@Override
	public void extractBackground(GuiGraphicsExtractor g, int mouseX, int mouseY, float partial) {
		g.fill(0, 0, width, height, 0xFF0C0E14);
	}

	@Override
	public void extractRenderState(GuiGraphicsExtractor g, int mouseX, int mouseY, float partial) {
		super.extractRenderState(g, mouseX, mouseY, partial);
		HeatMap map = HeatMap.get();
		// areas
		float cell = (float) (HeatMap.CELL / bpp);
		for (Map.Entry<String, HeatMap.Cell> e : map.cells().entrySet()) {
			String[] k = e.getKey().split(",");
			int ax = Integer.parseInt(k[0]), az = Integer.parseInt(k[1]);
			float x = sx((double) ax * HeatMap.CELL), y = sy((double) az * HeatMap.CELL);
			if (x > width || y > height || x + cell < 0 || y + cell < 0) continue;
			HeatMap.Cell c = e.getValue();
			float heat = (float) Math.min(1, c.average() / 30.0);
			int col = ColorUtil.lerp(0xFF263044, 0xFFFF7A1A, heat) & 0xFFFFFF;
			Draw.rect(g, x + 0.5f, y + 0.5f, cell - 1, cell - 1, 0xC0000000 | col);
			if (cell >= 26) Draw.text(g, String.valueOf(c.visits), x + 3, y + 3, 0x90FFFFFF);
		}
		// markers
		HeatMap.Marker hover = null;
		for (HeatMap.Marker m : map.markers()) {
			float x = sx(m.x + 0.5), y = sy(m.z + 0.5);
			if (x < -8 || y < -8 || x > width + 8 || y > height + 8) continue;
			int col = statusColor(m);
			Draw.circle(g, x, y, 4, 0xFF000000);
			Draw.circle(g, x, y, 3, 0xFF000000 | col);
			if (Math.abs(mouseX - x) <= 5 && Math.abs(mouseY - y) <= 5) hover = m;
		}
		// target and you
		HeatMap.Marker target = map.target();
		if (target != null) {
			float x = sx(target.x + 0.5), y = sy(target.z + 0.5);
			Draw.roundOutline(g, x - 7, y - 7, 14, 14, 7, 1.2f, 0xFFFFD43B, 0x00000000);
		}
		if (minecraft.player != null) {
			float x = sx(minecraft.player.getX()), y = sy(minecraft.player.getZ());
			double yaw = Math.toRadians(minecraft.player.getYRot());
			// you, with a dot on the side you are facing (yaw 0 faces south, +Z)
			Draw.circle(g, x, y, 3, 0xFFFFFFFF);
			Draw.circle(g, x - (float) Math.sin(yaw) * 6, y + (float) Math.cos(yaw) * 6, 1.6f, 0xFFFFFFFF);
		}

		// header and legend, on bands that keep the areas from showing through the text
		g.fill(0, 0, width, 42, 0xE60C0E14);
		g.fill(0, height - 28, width, height, 0xE60C0E14);
		Draw.round(g, 8, 8, font.width("Legit Heat Map") + 16, 16, 4, 0xC0151925);
		g.text(font, "Legit Heat Map", 16, 12, 0xFFEFEFEF, false);
		String scale = HeatMap.CELL + " blocks per square";
		g.text(font, scale, width - font.width(scale) - 10, 12, 0xFF929292, false);
		int ly = height - 20;
		int lx = 10;
		for (Object[] l : new Object[][]{{INTACT, "intact base"}, {MAYBE, "maybe raided"}, {RAIDED, "raided"}, {TRAIL, "trail"}}) {
			Draw.circle(g, lx + 3, ly + 4, 3, 0xFF000000 | (int) l[0]);
			g.text(font, (String) l[1], lx + 10, ly, 0xFFC9CED9, false);
			lx += 18 + font.width((String) l[1]);
		}
		Draw.rect(g, lx, ly, 8, 8, 0xFF263044);
		Draw.rect(g, lx + 8, ly, 8, 8, 0xFFFF7A1A);
		g.text(font, "quiet to busy area", lx + 20, ly, 0xFFC9CED9, false);
		g.text(font, "click: set target   right click: clear   drag: move   wheel: zoom", 10, 30, 0xFF929292, false);

		// tooltip
		List<String> tip = new ArrayList<>();
		if (hover != null) {
			tip.add((hover.type.equals("trail") ? "Trail" : "Base - " + hover.status) + "  " + hover.x + " " + hover.y + " " + hover.z);
			if (hover.label != null) tip.add(hover.label);
			tip.add(distance(hover.x, hover.z));
		} else {
			double wx = cx + (mouseX - width / 2.0) * bpp, wz = cz + (mouseY - height / 2.0) * bpp;
			HeatMap.Cell c = map.cells().get(HeatMap.cellKey(Math.floorDiv((int) Math.floor(wx), HeatMap.CELL), Math.floorDiv((int) Math.floor(wz), HeatMap.CELL)));
			if (c != null) tip.add(c.visits + " landings here, activity " + String.format(java.util.Locale.ROOT, "%.1f", c.average()) + " per landing");
			tip.add((int) wx + " " + (int) wz + "   " + distance((int) wx, (int) wz));
		}
		List<FormattedCharSequence> lines = new ArrayList<>();
		for (String s : tip) lines.add(Component.literal(s).getVisualOrderText());
		g.setTooltipForNextFrame(lines, mouseX, mouseY);
	}

	private String distance(int x, int z) {
		if (minecraft.player == null) return "";
		double d = Math.hypot(x + 0.5 - minecraft.player.getX(), z + 0.5 - minecraft.player.getZ());
		return d >= 1000 ? String.format(java.util.Locale.ROOT, "%.1f km away", d / 1000) : Math.round(d) + " m away";
	}

	@Override
	public boolean mouseClicked(MouseButtonEvent e, boolean doubleClick) {
		pressX = e.x();
		pressY = e.y();
		dragged = false;
		if (e.button() == 1) { HeatMap.get().setTarget(null); return true; }
		return true;
	}

	@Override
	public boolean mouseDragged(MouseButtonEvent e, double dx, double dy) {
		if (Math.abs(e.x() - pressX) + Math.abs(e.y() - pressY) > 3) dragged = true;
		cx -= dx * bpp;
		cz -= dy * bpp;
		return true;
	}

	@Override
	public boolean mouseReleased(MouseButtonEvent e) {
		if (e.button() == 0 && !dragged) select(e.x(), e.y());
		return true;
	}

	/** Makes the marker (or area) under the pointer the target. */
	public void select(double mouseX, double mouseY) {
		HeatMap map = HeatMap.get();
		for (HeatMap.Marker m : map.markers()) {
			if (Math.abs(mouseX - sx(m.x + 0.5)) <= 5 && Math.abs(mouseY - sy(m.z + 0.5)) <= 5) { map.setTarget(m); return; }
		}
		HeatMap.Marker spot = new HeatMap.Marker();
		spot.type = "spot";
		spot.status = "";
		spot.x = (int) Math.floor(cx + (mouseX - width / 2.0) * bpp);
		spot.z = (int) Math.floor(cz + (mouseY - height / 2.0) * bpp);
		spot.y = minecraft.player != null ? minecraft.player.getBlockY() : 64;
		spot.label = "chosen spot";
		map.setTarget(spot);
	}

	@Override
	public boolean mouseScrolled(double mx, double my, double sx, double sy) {
		// zoom around the pointer
		double wx = cx + (mx - width / 2.0) * bpp, wz = cz + (my - height / 2.0) * bpp;
		bpp = Math.max(1, Math.min(1024, bpp * (sy > 0 ? 0.8 : 1.25)));
		cx = wx - (mx - width / 2.0) * bpp;
		cz = wz - (my - height / 2.0) * bpp;
		return true;
	}

	/** Screen position of a world spot (for tests). */
	public float[] screenPos(int x, int z) { return new float[]{sx(x + 0.5), sy(z + 0.5)}; }
}
